from pysat.solvers import Glucose4
from pysat.card import CardEnc, EncType
from itertools import combinations

N = 21
W = 5
G = 7
S = 3  # group size

# var x[w][p][g] = golfer p in week w is in group g
def var(w, p, g):
    return w*N*G + p*G + g + 1

solver = Glucose4()
top_id = W*N*G

# Each golfer in exactly one group per week
for w in range(W):
    for p in range(N):
        lits = [var(w,p,g) for g in range(G)]
        # exactly one
        solver.add_clause(lits)
        for a,b in combinations(lits,2):
            solver.add_clause([-a,-b])

# Each group has exactly 3 golfers per week
for w in range(W):
    for g in range(G):
        lits = [var(w,p,g) for p in range(N)]
        cnf = CardEnc.equals(lits=lits, bound=S, top_id=top_id, encoding=EncType.seqcounter)
        top_id = max(top_id, max(abs(l) for c in cnf.clauses for l in c) if cnf.clauses else top_id)
        for c in cnf.clauses:
            solver.add_clause(c)

# Pair constraint: for each pair (p,q), at most one week same group
# y[w][p][q] = 1 iff p and q in same group in week w
# y = 1 iff exists g: x[w,p,g] & x[w,q,g]
# We use aux: for each (w,p,q,g) create aux, then sum across w,g <= 1
# Simpler: pair_same[w,p,q] := OR_g (x[w,p,g] AND x[w,q,g])
# Actually: at most one week where same group. For each pair, sum over weeks of (same group indicator) <=1.
# Indicator per (w,p,q): define aux z[w,p,q], and z[w,p,q] <=> exists g with both in g.
# We need z true if any g both, and constrain sum z_w <=1.

# For each pair (p,q), for each week w, for each group g, create clause:
# x[w,p,g] & x[w,q,g] -> z[w,p,q]
# Then sum_w z[w,p,q] <= 1.

z_vars = {}
for p,q in combinations(range(N),2):
    for w in range(W):
        top_id += 1
        z_vars[(w,p,q)] = top_id

for p,q in combinations(range(N),2):
    for w in range(W):
        z = z_vars[(w,p,q)]
        for g in range(G):
            # x[w,p,g] & x[w,q,g] -> z
            solver.add_clause([-var(w,p,g), -var(w,q,g), z])

# at most one week same
for p,q in combinations(range(N),2):
    lits = [z_vars[(w,p,q)] for w in range(W)]
    cnf = CardEnc.atmost(lits=lits, bound=1, top_id=top_id, encoding=EncType.seqcounter)
    if cnf.clauses:
        top_id = max(top_id, max(abs(l) for c in cnf.clauses for l in c))
    for c in cnf.clauses:
        solver.add_clause(c)

print("solving...")
res = solver.solve()
print(res)
if res:
    model = set(l for l in solver.get_model() if l>0)
    sched = []
    for w in range(W):
        for p in range(N):
            for g in range(G):
                if var(w,p,g) in model:
                    sched.append(g)
                    break
    print(sched)
    # verify
    for w in range(W):
        groups = {}
        for p in range(N):
            groups.setdefault(sched[w*N+p],[]).append(p)
        assert len(groups)==7
        for g,ps in groups.items():
            assert len(ps)==3
    pairs=set()
    for w in range(W):
        groups = {}
        for p in range(N):
            groups.setdefault(sched[w*N+p],[]).append(p)
        for ps in groups.values():
            for a,b in combinations(ps,2):
                assert (a,b) not in pairs
                pairs.add((a,b))
    print("verified")
